// Generated by the runner and overwritten on every run; do not edit.
package warmup

import (
	"strconv"
	"sync"
	"testing"
	"time"

	"lab/dojo"
)

// poolCheck runs RunPool with a job that records how many run at once, and draws each job on the timeline.
func poolCheck(t *testing.T, nJobs, n int) {
	tr := dojo.NewTrace()
	defer tr.Save(t.Name())
	jobs := make([]int, nJobs)
	for i := range jobs {
		jobs[i] = i * 10
	}
	var mu sync.Mutex
	cur, peak := 0, 0
	f := func(j int) int {
		id := strconv.Itoa(j / 10)
		mu.Lock()
		cur++
		if cur > peak {
			peak = cur
		}
		mu.Unlock()
		tr.Add("job "+id, "begin", id, "J"+id, false)
		time.Sleep(60 * time.Millisecond)
		tr.Add("job "+id, "end", id, "", false)
		mu.Lock()
		cur--
		mu.Unlock()
		return j + 1
	}
	res := RunPool(jobs, n, f)
	for i, j := range jobs {
		if i >= len(res) || res[i] != j+1 {
			fail(t, "pool_order", say("results[%d] 应该是 f(jobs[%d]) = %d。", "results[%d] should be f(jobs[%d]) = %d.", i, i, j+1))
		}
	}
	if peak > n {
		fail(t, "pool_too_many", say("同时运行了 %d 个任务，上限是 %d。", "%d jobs ran at once; the limit is %d.", peak, n))
	}
	if peak < n {
		fail(t, "pool_serial", say("同时运行的最多只有 %d 个，应该用满 %d 个。", "At most %d ran at once; all %d should be used.", peak, n))
	}
}

func TestLv2_PoolOf3(t *testing.T) { poolCheck(t, 9, 3) }
func TestLv2_PoolOf1(t *testing.T) { poolCheck(t, 4, 1) }
func TestLv2_Wide(t *testing.T)    { poolCheck(t, 5, 5) }
